import React from 'react'
import { Modal, message } from 'antd'
import DetailModalWrapper from './style'
import moment from 'moment-timezone'
import PropTypes from 'prop-types'
import { imgIcon } from '../../constant'
const { copyToClipBoard } = imgIcon

const DetailApprovalModal = ({
  detailModalData,
  closeModal,
  isOpen,
  rejectApprovalRequest,
  approveApprovalRequest
}) => {
  const handleApprove = () => {
    approveApprovalRequest({
      body: {
        id: detailModalData?.id,
        identifier: detailModalData?.identifier
      }
    })
  }

  const handleReject = () => {
    rejectApprovalRequest({
      body: {
        id: detailModalData?.id,
        identifier: detailModalData?.identifier
      }
    })
  }

  const renderWithClipBoard = (data) => {
    return (
      <div className='with-clipboard'>
        <span>{data}</span>
        <img
          src={copyToClipBoard}
          alt='clip-icon'
          onClick={() => {
            navigator.clipboard.writeText(data)
            message.success('Copied')
          }}
        />
      </div>
    )
  }

  const dateFormat = (date) => {
    return moment(date).tz('Asia/Jakarta').format('lll')
  }

  return (
    <Modal title='' visible={isOpen} footer={null} onCancel={closeModal}>
      <DetailModalWrapper>
        <div className='container'>
          <span>Zoho Ticket ID</span>
          <span>{renderWithClipBoard(detailModalData?.ticket_id)}</span>
        </div>

        <div className='container'>
          <span>Application Number</span>
          <span className='blue'>{detailModalData?.identifier}</span>
        </div>

        <div className='container'>
          <span>Requested At</span>
          <span>{dateFormat(detailModalData?.created_at)}</span>
        </div>

        <div className='container'>
          <span>Requested By</span>
          <span>{detailModalData?.requested_by}</span>
        </div>

        <div className='container'>
          <span>Requested Type</span>
          <span>{detailModalData?.action}</span>
        </div>

        <div className='container'>
          {!detailModalData?.request_payload?.response?.old_phone
            ? <span>DOES NOT EXIST</span>
            : <span>{detailModalData?.request_payload?.response?.old_phone}</span>}
          <span>{detailModalData?.request_payload?.response?.new_phone}</span>
        </div>

        <div className='container btn2'>
          <button className='reject' onClick={handleReject}>
            Reject
          </button>
          <button className='approve' onClick={handleApprove}>
            Approve
          </button>
        </div>
      </DetailModalWrapper>
    </Modal>
  )
}

DetailApprovalModal.prototype = {
  detailModalData: PropTypes.object,
  closeModal: PropTypes.func,
  isOpen: PropTypes.bool,
  rejectApprovalRequest: PropTypes.func,
  changePhoneNumberRequest: PropTypes.func
}

export default DetailApprovalModal
